"""Use the pinned rusty_v8 source snapshot without fetching native submodules."""

import argparse
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import tarfile
import tempfile
import tomllib
from urllib.request import urlopen

ROOT = Path(__file__).resolve().parents[2]
SOURCE_NAME = "fork-rusty-v8-upstream"
VENDOR_NAME = "fork-rusty-v8-prebuilt"


def digest(path: Path) -> str:
    with path.open("rb") as source:
        return hashlib.file_digest(source, "sha256").hexdigest()


def read_pin(workspace: Path, pins: Path) -> dict:
    manifest = tomllib.loads((workspace / "Cargo.toml").read_text())
    patch = manifest["patch"]["crates-io"]["v8"]
    packages = tomllib.loads((workspace / "Cargo.lock").read_text())["package"]
    versions = [package for package in packages if package["name"] == "v8"]
    if len(versions) != 1:
        raise ValueError("Expected one locked v8 package")
    package = versions[0]
    pin = json.loads((pins / f"rusty_v8_{package['version'].replace('.', '_')}_source.json").read_text())
    repository, revision = pin["repository"], pin["revision"]
    if not re.fullmatch(r"https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+\.git", repository):
        raise ValueError("Expected a pinned GitHub source repository")
    if not re.fullmatch(r"[0-9a-f]{40}", revision) or not re.fullmatch(r"[0-9a-f]{64}", pin["archiveSha256"]):
        raise ValueError("Invalid source revision or archive checksum")
    expected_source = f"git+{repository}?rev={revision}#{revision}"
    if patch != {"git": repository, "rev": revision} or package.get("source") != expected_source or package["version"] != pin["version"]:
        raise ValueError("V8 source pin must match both the workspace patch and Cargo.lock")
    return pin


def source_config(workspace: Path, vendor: Path, pin: dict) -> tuple[Path, str]:
    config_path = workspace / ".cargo/config.toml"
    original = config_path.read_text() if config_path.exists() else ""
    config = tomllib.loads(original)
    if {SOURCE_NAME, VENDOR_NAME} & config.get("source", {}).keys():
        raise ValueError("V8 source replacement is already configured")
    if "V8_FROM_SOURCE" in config.get("env", {}):
        raise ValueError("Refusing to override an existing V8_FROM_SOURCE configuration")
    # Cargo resolves config paths relative to the parent of .cargo/, not .cargo/.
    relative = Path(os.path.relpath(vendor, workspace)).as_posix()
    addition = (
        "\n# Generated by prepare_rusty_v8_source.py for prebuilt-only CI builds.\n"
        f"[source.{SOURCE_NAME}]\n"
        f"git = {json.dumps(pin['repository'])}\n"
        f"rev = {json.dumps(pin['revision'])}\n"
        f"replace-with = {json.dumps(VENDOR_NAME)}\n\n"
        f"[source.{VENDOR_NAME}]\n"
        f"directory = {json.dumps(relative)}\n\n"
        "[env.V8_FROM_SOURCE]\nvalue = \"0\"\nforce = true\n"
    )
    result = original.rstrip() + "\n" + addition
    tomllib.loads(result)
    return config_path, result


def extract_source(archive: Path, package: Path, pin: dict) -> None:
    if digest(archive) != pin["archiveSha256"]:
        raise ValueError("V8 source archive checksum mismatch")
    prefix = f"{pin['repository'].rsplit('/', 1)[1].removesuffix('.git')}-{pin['revision']}"
    files = {}
    with tarfile.open(archive, "r:gz") as source:
        for member in source.getmembers():
            path = PurePosixPath(member.name)
            if path.is_absolute() or ".." in path.parts or "\\" in member.name or not path.parts or path.parts[0] != prefix:
                raise ValueError("Unsafe V8 source archive path")
            if member.isdir():
                continue
            if not member.isfile() or len(path.parts) < 2:
                raise ValueError("V8 source archive must contain only regular files")
            relative = PurePosixPath(*path.parts[1:]).as_posix()
            if relative in files or relative == ".cargo-checksum.json":
                raise ValueError("Duplicate or reserved V8 source archive file")
            content = source.extractfile(member)
            if content is None:
                raise ValueError("Missing V8 source archive contents")
            destination = package / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            with content, destination.open("wb") as output:
                shutil.copyfileobj(content, output)
            destination.chmod(0o755 if member.mode & 0o111 else 0o644)
            files[relative] = digest(destination)
    manifest = tomllib.loads((package / "Cargo.toml").read_text())
    if manifest["package"]["name"] != "v8" or manifest["package"]["version"] != pin["version"]:
        raise ValueError("V8 source archive package identity mismatch")
    for required in ["build.rs", "src/lib.rs", "src/binding.rs"]:
        if required not in files:
            raise ValueError(f"Missing V8 source file: {required}")
    (package / ".cargo-checksum.json").write_text(
        json.dumps({"files": files, "package": None}, sort_keys=True) + "\n", encoding="utf-8",
    )


def prepare(workspace: Path, vendor: Path, *, archive: Path | None = None, pins: Path = ROOT / "third_party/v8") -> dict:
    workspace, vendor = workspace.resolve(), vendor.resolve()
    pin = read_pin(workspace, pins)
    config_path, config = source_config(workspace, vendor, pin)
    if vendor.exists():
        raise ValueError("Refusing to overwrite an existing V8 vendor directory")
    vendor.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=".v8-source-", dir=vendor.parent) as temporary:
        staging = Path(temporary)
        if archive is None:
            archive = staging / "source.tar.gz"
            repository = pin["repository"].removeprefix("https://github.com/").removesuffix(".git")
            url = f"https://codeload.github.com/{repository}/tar.gz/{pin['revision']}"
            with urlopen(url, timeout=60) as response, archive.open("wb") as output:
                shutil.copyfileobj(response, output)
        package = staging / "vendor" / f"v8-{pin['version']}"
        extract_source(archive, package, pin)
        size = archive.stat().st_size
        (staging / "vendor").rename(vendor)
    config_path.parent.mkdir(parents=True, exist_ok=True)
    config_path.write_text(config, encoding="utf-8")
    print(f"Prepared v8 {pin['version']} at {pin['revision']}: {size:,} source archive bytes; native submodules omitted")
    return pin


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", type=Path, default=ROOT / "codex-rs")
    parser.add_argument("--vendor-dir", type=Path, default=ROOT / ".cache/fork-v8")
    parser.add_argument("--archive", type=Path, help="Use an already downloaded, checksum-verified source archive")
    args = parser.parse_args()
    prepare(args.workspace, args.vendor_dir, archive=args.archive)


if __name__ == "__main__":
    main()
